import React, { useEffect, useRef, useState } from 'react';
import { BlackboxPlayback } from './components/BlackboxPlayback';
import { Header } from './components/Header';
import { ManualControls } from './components/ManualControls';
import { MissionPlanner } from './components/MissionPlanner';
import { PidTuningPanel } from './components/PidTuningPanel';
import { PrimaryFlightDisplay } from './components/PrimaryFlightDisplay';
import { TelemetryGraph } from './components/TelemetryGraph';
import { TelemetryStrip } from './components/TelemetryStrip';
import { TestFlightSuite } from './components/TestFlightSuite';
import { Viewport3D } from './components/Viewport3D';
import { AutopilotEngine } from './engine/autopilot';
import { EnvironmentEngine } from './engine/environment';
import { PhysicsEngine } from './engine/physicsEngine';
import { SensorEngine } from './engine/sensors';
import { TestScenarioRunner } from './engine/testScenarioRunner';
import { flightRecorder } from './services/flightRecorder';
import { PRESET_FLIGHT_PLANS } from './services/missionPresets';
import { soundEngine } from './services/soundEngine';
import { PilotInput, UAVPIDConfig } from './types/controls';
import { Waypoint } from './types/mission';
import { ArmState, FlightMode, TelemetryPacket } from './types/telemetry';

export const App: React.FC = () => {
  // Engine Instances
  const physicsRef = useRef(new PhysicsEngine());
  const autopilotRef = useRef(new AutopilotEngine());
  const envRef = useRef(new EnvironmentEngine());
  const sensorsRef = useRef(new SensorEngine());
  const testRunnerRef = useRef(new TestScenarioRunner());

  // React State for UI Telemetry (updated at 30-60Hz)
  const [telemetry, setTelemetry] = useState<TelemetryPacket>(() => {
    const p = physicsRef.current.getState();
    const s = sensorsRef.current.update(p, 0);
    return {
      timestamp: 0,
      armState: 'DISARMED',
      flightMode: 'DISARMED',
      position: p.position,
      velocity: p.velocity,
      attitude: p.attitude,
      sensors: s,
      motors: p.motors,
      battery: p.battery,
      activeWaypointIndex: 0,
      distanceToHome: 0,
      distanceToWaypoint: 0,
      warnings: [],
    };
  });

  const [pilotInput, setPilotInput] = useState<PilotInput>({ throttle: 0.5, roll: 0, pitch: 0, yaw: 0 });
  const [isAudioMuted, setIsAudioMuted] = useState(true);
  const [rightPanelTab, setRightPanelTab] = useState<'MISSION' | 'FAT_SUITE' | 'PID_TUNER'>('FAT_SUITE');
  const [waypoints, setWaypoints] = useState<Waypoint[]>(PRESET_FLIGHT_PLANS[0].waypoints);
  const [frameCount, setFrameCount] = useState(0);
  const [isReplaying, setIsReplaying] = useState(false);
  const [replayIndex, setReplayIndex] = useState(0);

  // Initialize autopilot waypoints
  useEffect(() => {
    autopilotRef.current.waypoints = waypoints;
  }, [waypoints]);

  // Main Simulation Loop (60Hz)
  useEffect(() => {
    let animId: number;
    let lastTime = performance.now();

    const loop = (now: number) => {
      const dt = Math.min(0.033, (now - lastTime) / 1000);
      lastTime = now;

      const physics = physicsRef.current;
      const autopilot = autopilotRef.current;
      const env = envRef.current;
      const sensors = sensorsRef.current;
      const runner = testRunnerRef.current;

      if (!isReplaying) {
        // 1. Environment Step
        const envState = env.update(dt, physics.getState().position.y);

        // 2. Autopilot Computation
        const motorOutputs = autopilot.computeMotorOutputs(physics.getState(), dt, pilotInput);
        for (let i = 0; i < 4; i++) {
          physics.setMotorThrottle(i, motorOutputs[i]);
        }

        // 3. Physics Step
        const uavState = physics.step(dt, envState.windVector, envState.airDensity);

        // 4. Sensors Step
        const sensorData = sensors.update(uavState, Math.sqrt(uavState.velocity.x * uavState.velocity.x + uavState.velocity.z * uavState.velocity.z));

        // 5. Test Runner Step
        runner.update(dt, uavState, physics, autopilot, env);

        // 6. Sound Engine Update
        const avgRpm = uavState.motors.reduce((acc, m) => acc + m.rpm, 0) / 4;
        soundEngine.update(avgRpm, sensorData.airspeedMps);

        // 7. Distance & Warnings Calculation
        const distHome = Math.sqrt(uavState.position.x * uavState.position.x + uavState.position.z * uavState.position.z);
        const warnings: string[] = [];
        if (uavState.battery.percent < 20) warnings.push('BATTERY CRITICAL');
        if (distHome > 60) warnings.push('GEOFENCE BREACH');
        if (uavState.hasCrashed) warnings.push('AIRCRAFT CRASH DETECTED');

        const packet: TelemetryPacket = {
          timestamp: uavState.timestamp,
          armState: autopilot.armState,
          flightMode: autopilot.flightMode,
          position: { ...uavState.position },
          velocity: { ...uavState.velocity },
          attitude: { ...uavState.attitude },
          sensors: sensorData,
          motors: uavState.motors.map((m) => ({ ...m })),
          battery: { ...uavState.battery },

content.content:
