127	        // Record Telemetry
128	        flightRecorder.addFrame(packet);
129	        setFrameCount(flightRecorder.getFrameCount());
130	        setTelemetry(packet);
131	      } else {
132	        // Replay Mode
133	        const frame = flightRecorder.getFrameAt(replayIndex);
134	        if (frame) {
135	          setTelemetry(frame);
136	          setReplayIndex((prev) => (prev < flightRecorder.getFrameCount() - 1 ? prev + 1 : 0));
137	        }
138	      }
139	
140	      animId = requestAnimationFrame(loop);
141	    };
