150	    autopilotRef.current.setArmState(nextState);
151	    if (nextState === 'ARMED') {
152	      autopilotRef.current.setFlightMode('ALT_HOLD');
153	      autopilotRef.current.targetPosition.y = 5.0; // Auto climb to 5m hover
154	    }
155	  };
156	
157	  const handleSelectFlightMode = (mode: FlightMode) => {
158	    autopilotRef.current.setFlightMode(mode);
159	    if (mode === 'ALT_HOLD' || mode === 'POS_HOLD') {
160	      autopilotRef.current.targetPosition = { ...physicsRef.current.getState().position };
161	      if (autopilotRef.current.targetPosition.y < 2.0) autopilotRef.current.targetPosition.y = 5.0;
162	    }
163	  };
164	
165	  const handleToggleAudio = () => {
166	    const next = !isAudioMuted;
167	    setIsAudioMuted(next);
168	    soundEngine.setMute(next);
169	  };
170	
171	  const handleResetUav = () => {
172	    physicsRef.current.reset(0);
173	    autopilotRef.current.setArmState('DISARMED');
174	    autopilotRef.current.resetIntegrators();
175	  };
176	
177	  const handleInjectImpulse = (axis: 'roll' | 'pitch' | 'yaw') => {
178	    const s = physicsRef.current.getState();
179	    if (axis === 'roll') s.angularVelocity.p += 2.0;
180	    if (axis === 'pitch') s.angularVelocity.q += 2.0;
181	    if (axis === 'yaw') s.angularVelocity.r += 2.5;
182	  };
183	
184	  return (
185	    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: 'var(--bg-primary)' }}>
186	      {/* 1. Header Control Bar */}
187	      <Header
188	        telemetry={telemetry}
189	        armState={autopilotRef.current.armState}
190	        flightMode={autopilotRef.current.flightMode}
191	        isAudioMuted={isAudioMuted}
192	        onToggleArm={handleToggleArm}
193	        onSelectFlightMode={handleSelectFlightMode}
194	        onToggleAudio={handleToggleAudio}
195	        onResetUav={handleResetUav}
196	      />
197	
198	      {/* 2. Telemetry Ribbon Strip */}
199	      <TelemetryStrip
200	        telemetry={telemetry}
201	        windSpeed={envRef.current.update(0, 0).baseWindSpeed}
202	        windHeading={envRef.current.update(0, 0).windDirectionDeg}
203	      />
204	
205	      {/* 3. Main Dashboard Workspace */}
206	      <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr 380px', gap: '8px', padding: '4px 8px 8px 8px', flex: 1, minHeight: 0 }}>
207	        {/* Left Column: PFD, Virtual Sticks, Flight Recorder */}
208	        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', overflowY: 'auto' }}>
209	          <PrimaryFlightDisplay
210	            telemetry={telemetry}
211	            targetAltitude={autopilotRef.current.targetPosition.y}
212	            targetHeading={autopilotRef.current.targetHeading}
213	          />
214	          <ManualControls
215	            pilotInput={pilotInput}
216	            onChangeInput={(inp) => setPilotInput((prev) => ({ ...prev, ...inp }))}
217	          />
218	          <BlackboxPlayback
219	            frameCount={frameCount}
220	            isReplaying={isReplaying}

