        activeWaypointIndex: autopilot.activeWaypointIndex,
        distanceToHome: distHome,
        distanceToWaypoint: 0,
        warnings,
      };

      // Record Telemetry
      flightRecorder.addFrame(packet);
      setFrameCount(flightRecorder.getFrameCount());
      setTelemetry(packet);
    } else {
      // Replay Mode
      const frame = flightRecorder.getFrameAt(replayIndex);
      if (frame) {
        setTelemetry(frame);
        setReplayIndex((prev) => (prev < flightRecorder.getFrameCount() - 1 ? prev + 1 : 0));
      }
    }

    animId = requestAnimationFrame(loop);
  };

  animId = requestAnimationFrame(loop);
  return () => cancelAnimationFrame(animId);
}, [isReplaying, replayIndex, pilotInput]);

// Handlers
const handleToggleArm = () => {
  const nextState: ArmState = autopilotRef.current.armState === 'ARMED' ? 'DISARMED' : 'ARMED';
  autopilotRef.current.setArmState(nextState);
  if (nextState === 'ARMED') {
    autopilotRef.current.setFlightMode('ALT_HOLD');
    autopilotRef.current.targetPosition.y = 5.0; // Auto climb to 5m hover
  }
};

const handleSelectFlightMode = (mode: FlightMode) => {
  autopilotRef.current.setFlightMode(mode);
  if (mode === 'ALT_HOLD' || mode === 'POS_HOLD') {
    autopilotRef.current.targetPosition = { ...physicsRef.current.getState().position };
    if (autopilotRef.current.targetPosition.y < 2.0) autopilotRef.current.targetPosition.y = 5.0;
  }
};

const handleToggleAudio = () => {
  const next = !isAudioMuted;
  setIsAudioMuted(next);
  soundEngine.setMute(next);
};

const handleResetUav = () => {
  physicsRef.current.reset(0);
  autopilotRef.current.setArmState('DISARMED');
  autopilotRef.current.resetIntegrators();
};

const handleInjectImpulse = (axis: 'roll' | 'pitch' | 'yaw') => {
  const s = physicsRef.current.getState();
  if (axis === 'roll') s.angularVelocity.p += 2.0;
  if (axis === 'pitch') s.angularVelocity.q += 2.0;
  if (axis === 'yaw') s.angularVelocity.r += 2.5;
};

return (
  <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: 'var(--bg-primary)' }}>
    {/* 1. Header Control Bar */}
    <Header
      telemetry={telemetry}
      armState={autopilotRef.current.armState}
      flightMode={autopilotRef.current.flightMode}
      isAudioMuted={isAudioMuted}
      onToggleArm={handleToggleArm}
      onSelectFlightMode={handleSelectFlightMode}
      onToggleAudio={handleToggleAudio}
      onResetUav={handleResetUav}
    />

    {/* 2. Telemetry Ribbon Strip */}
    <TelemetryStrip
      telemetry={telemetry}
      windSpeed={envRef.current.update(0, 0).baseWindSpeed}
      windHeading={envRef.current.update(0, 0).windDirectionDeg}
    />

    {/* 3. Main Dashboard Workspace */}
    <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr 380px', gap: '8px', padding: '4px 8px 8px 8px', flex: 1, minHeight: 0 }}>
      {/* Left Column: PFD, Virtual Sticks, Flight Recorder */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', overflowY: 'auto' }}>
        <PrimaryFlightDisplay
          telemetry={telemetry}
          targetAltitude={autopilotRef.current.targetPosition.y}
          targetHeading={autopilotRef.current.targetHeading}
        />
        <ManualControls
          pilotInput={pilotInput}
          onChangeInput={(inp) => setPilotInput((prev) => ({ ...prev, ...inp }))}
        />
        <BlackboxPlayback
          frameCount={frameCount}
          isReplaying={isReplaying}

