import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { Waypoint } from '../types/mission';
import { TelemetryPacket } from '../types/telemetry';
import { Vector3D } from '../types/uav';

interface Viewport3DProps {
  telemetry: TelemetryPacket;
  waypoints: Waypoint[];
  windVector: Vector3D;
}

export type CameraMode = 'CHASE' | 'FPV' | 'TACTICAL' | 'GROUND';

export const Viewport3D: React.FC<Viewport3DProps> = ({
  telemetry,
  waypoints,
  windVector,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [cameraMode, setCameraMode] = useState<CameraMode>('CHASE');

  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const uavGroupRef = useRef<THREE.Group | null>(null);
  const rotorMeshesRef = useRef<THREE.Mesh[]>([]);
  const trailLineRef = useRef<THREE.Line | null>(null);
  const trailPointsRef = useRef<THREE.Vector3[]>([]);
  const waypointsGroupRef = useRef<THREE.Group | null>(null);
  const windsockRef = useRef<THREE.Group | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 1. Scene, Camera, Renderer
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.background = new THREE.Color(0x06080d);
    scene.fog = new THREE.FogExp2(0x06080d, 0.005);

    const camera = new THREE.PerspectiveCamera(55, container.clientWidth / container.clientHeight, 0.2, 800);
    cameraRef.current = camera;
    camera.position.set(0, 8, 14);

    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    rendererRef.current = renderer;
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    container.appendChild(renderer.domElement);

    // 2. Lighting
    const ambient = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambient);

    const sun = new THREE.DirectionalLight(0xdff4ff, 1.2);
    sun.position.set(40, 80, 50);
    sun.castShadow = true;
    scene.add(sun);

    // 3. Airfield & Ground
    const grid = new THREE.GridHelper(300, 60, 0x00f2fe, 0x162233);
    grid.position.y = 0;
    scene.add(grid);

    // Runway tarmac
    const tarmacGeo = new THREE.PlaneGeometry(16, 120);
    const tarmacMat = new THREE.MeshStandardMaterial({ color: 0x111622, roughness: 0.8 });
    const tarmac = new THREE.Mesh(tarmacGeo, tarmacMat);
    tarmac.rotation.x = -Math.PI / 2;
    tarmac.position.set(0, 0.02, 0);
    scene.add(tarmac);

    // Helipad / Launch circle
    const padGeo = new THREE.RingGeometry(2.5, 3.2, 32);
    const padMat = new THREE.MeshBasicMaterial({ color: 0x00f2fe, side: THREE.DoubleSide });
    const pad = new THREE.Mesh(padGeo, padMat);
    pad.rotation.x = -Math.PI / 2;
    pad.position.set(0, 0.04, 0);
    scene.add(pad);

    // 4. Build 3D Quadcopter Mesh
    const uav = new THREE.Group();
    uavGroupRef.current = uav;

    // Carbon Body Center
    const bodyGeo = new THREE.BoxGeometry(0.35, 0.08, 0.45);
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0x1a2130, roughness: 0.3, metalness: 0.8 });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    uav.add(body);

    // Canopy / Top Dome
    const canopyGeo = new THREE.SphereGeometry(0.12, 16, 16);
    const canopyMat = new THREE.MeshStandardMaterial({ color: 0x00f2fe, roughness: 0.2, metalness: 0.9 });
    const canopy = new THREE.Mesh(canopyGeo, canopyMat);
    canopy.position.set(0, 0.06, -0.05);
    uav.add(canopy);

