export interface Vector3D {
  x: number;
  y: number;
  z: number;
}

export interface Attitude3D {
  roll: number;  // Radians (-PI to PI)
  pitch: number; // Radians (-PI/2 to PI/2)
  yaw: number;   // Radians (-PI to PI, 0 = North, PI/2 = East)
}

export interface AngularRate3D {
  p: number; // Roll rate (rad/s)
  q: number; // Pitch rate (rad/s)
  r: number; // Yaw rate (rad/s)
}

export interface UAVPhysicalParams {
  mass: number;           // Total mass (kg)
  armLength: number;      // Distance from center to motor (m)
  dragCoefficient: number;// Translational drag coeff (Cd * A)
  angularDragCoeff: number;
  ixx: number;            // Moment of inertia X (kg*m^2)
  iyy: number;            // Moment of inertia Y (kg*m^2)
  izz: number;            // Moment of inertia Z (kg*m^2)
  thrustCoefficient: number; // Thrust factor (N / (RPM/1000)^2)
  torqueCoefficient: number; // Reaction torque factor (N*m / (RPM/1000)^2)
  maxRpm: number;         // Max motor RPM
  motorTimeConstant: number; // Motor spool-up latency (seconds)
}

export interface MotorState {
  id: number;
  rpm: number;
  thrust: number;      // Newtons
  targetThrottle: number; // 0.0 - 1.0
  health: number;      // 0.0 (dead) to 1.0 (nominal)
}

export interface BatteryState {
  voltage: number;         // Volts (nominal 22.2V for 6S)
  current: number;         // Amperes
  capacityUsed: number;    // mAh
  totalCapacity: number;   // mAh (e.g. 5000 mAh)
  percent: number;         // 0 - 100%
  cellVoltages: number[];  // 6S cell voltages (e.g. 3.7V - 4.2V)
}

export interface UAVDynamicState {
  position: Vector3D;      // X=East, Y=Altitude/Up, Z=South (m)
  velocity: Vector3D;      // m/s in world frame
  acceleration: Vector3D;  // m/s^2 in world frame
  attitude: Attitude3D;    // Roll, Pitch, Yaw
  angularVelocity: AngularRate3D;
  motors: MotorState[];
  battery: BatteryState;
  timestamp: number;       // Elapsed simulation seconds
  isGrounded: boolean;
  hasCrashed: boolean;
}

