import { ArmDimensions, DEFAULT_ARM_DIMENSIONS, DEFAULT_JOINT_CONFIGS } from '../types/kinematics';
import { Euler3D, Pose3D, Vector3D } from '../types/arm';

export interface JointPositions3D {
  base: Vector3D;
  shoulder: Vector3D;
  elbow: Vector3D;
  wristPitch: Vector3D;
  wristRoll: Vector3D;
  tcp: Vector3D;
}

export class KinematicsEngine {
  private dims: ArmDimensions;

  constructor(dims: ArmDimensions = DEFAULT_ARM_DIMENSIONS) {
    this.dims = dims;
  }

  /**
   * Forward Kinematics: Calculates all intermediate joint 3D positions and final TCP pose.
   * Coordinate system: Y = Up, X = Right/Forward, Z = Depth/Lateral
   */
  public forwardKinematics(anglesDeg: number[]): { positions: JointPositions3D; tcpPose: Pose3D } {
    const j1 = (anglesDeg[0] * Math.PI) / 180; // Base yaw
    const j2 = (anglesDeg[1] * Math.PI) / 180; // Shoulder pitch
    const j3 = (anglesDeg[2] * Math.PI) / 180; // Elbow pitch
    const j4 = (anglesDeg[3] * Math.PI) / 180; // Wrist pitch
    const j5 = (anglesDeg[4] * Math.PI) / 180; // Wrist roll

    // Base
    const base: Vector3D = { x: 0, y: 0, z: 0 };
    // Shoulder (height d1)
    const shoulder: Vector3D = { x: 0, y: this.dims.baseHeightMm, z: 0 };

    // Cumulative pitch angles
    const theta2 = j2;
    const theta23 = j2 + j3;
    const theta234 = j2 + j3 + j4;

    // Planar reach in arm plane (r = radial distance from base axis, y = height)
    const rElbow = this.dims.upperArmLengthMm * Math.sin(theta2);
    const yElbow = shoulder.y + this.dims.upperArmLengthMm * Math.cos(theta2);

    const rWristPitch = rElbow + this.dims.forearmLengthMm * Math.sin(theta23);
    const yWristPitch = yElbow + this.dims.forearmLengthMm * Math.cos(theta23);

    const rWristRoll = rWristPitch + this.dims.wristPitchMm * Math.sin(theta234);
    const yWristRoll = yWristPitch + this.dims.wristPitchMm * Math.cos(theta234);

    const totalToolDist = this.dims.wristRollMm + this.dims.gripperOffsetMm;
    const rTcp = rWristRoll + totalToolDist * Math.sin(theta234);
    const yTcp = yWristRoll + totalToolDist * Math.cos(theta234);

    // Project planar (r, y) into 3D world with base rotation j1
    // J1 = 0 => pointing along +X axis
    const toWorld = (r: number, y: number): Vector3D => ({
      x: r * Math.cos(j1),
      y: y,
      z: -r * Math.sin(j1),
    });

    const elbow = toWorld(rElbow, yElbow);
    const wristPitch = toWorld(rWristPitch, yWristPitch);
    const wristRoll = toWorld(rWristRoll, yWristRoll);
    const tcp = toWorld(rTcp, yTcp);

    const orientation: Euler3D = {
      pitch: Number(((theta234 * 180) / Math.PI).toFixed(1)),
      roll: Number((anglesDeg[4]).toFixed(1)),
      yaw: Number((anglesDeg[0]).toFixed(1)),
    };

    return {
      positions: { base, shoulder, elbow, wristPitch, wristRoll, tcp },
      tcpPose: { position: tcp, orientation },
    };
  }

  /**
   * Fast Numerical Inverse Kinematics (Jacobian Transpose with Joint Limits & Damping)
   */
  public inverseKinematics(
    targetPos: Vector3D,
    currentAngles: number[],
    targetPitchDeg = 0
  ): { anglesDeg: number[]; converged: boolean; errorMm: number } {
    const angles = [...currentAngles];
    const maxIterations = 35;
    const toleranceMm = 1.0;
    const alpha = 0.0004; // Step rate

    for (let iter = 0; iter < maxIterations; iter++) {
      const { tcpPose } = this.forwardKinematics(angles);
      const dx = targetPos.x - tcpPose.position.x;
      const dy = targetPos.y - tcpPose.position.y;
      const dz = targetPos.z - tcpPose.position.z;
      const errDist = Math.sqrt(dx * dx + dy * dy + dz * dz);

      if (errDist < toleranceMm) {
        return { anglesDeg: angles, converged: true, errorMm: errDist };
      }

      // Analytical base yaw
      const targetBaseYaw = (Math.atan2(-targetPos.z, targetPos.x) * 180) / Math.PI;
      angles[0] += (targetBaseYaw - angles[0]) * 0.25;

      // Numeric gradient for arm joints (J2, J3, J4)
      const delta = 0.1;
      for (let j = 1; j <= 3; j++) {
        angles[j] += delta;
        const fkPlus = this.forwardKinematics(angles).tcpPose.position;
        angles[j] -= delta;

        const jx = (fkPlus.x - tcpPose.position.x) / delta;
        const jy = (fkPlus.y - tcpPose.position.y) / delta;
        const jz = (fkPlus.z - tcpPose.position.z) / delta;

        const dAngle = alpha * (jx * dx + jy * dy + jz * dz);
        angles[j] += dAngle;

        // Clamp to joint limits
        const cfg = DEFAULT_JOINT_CONFIGS[j];
        angles[j] = Math.max(cfg.minDeg, Math.min(cfg.maxDeg, angles[j]));
      }

      // Wrist pitch orient towards target pitch
      angles[3] += (targetPitchDeg - (angles[1] + angles[2] + angles[3])) * 0.1;
      const cfg3 = DEFAULT_JOINT_CONFIGS[3];
      angles[3] = Math.max(cfg3.minDeg, Math.min(cfg3.maxDeg, angles[3]));
    }

    const finalFk = this.forwardKinematics(angles).tcpPose.position;
    const finalErr = Math.sqrt(
      Math.pow(targetPos.x - finalFk.x, 2) +
      Math.pow(targetPos.y - finalFk.y, 2) +
      Math.pow(targetPos.z - finalFk.z, 2)
    );

    return { anglesDeg: angles, converged: finalErr < 5.0, errorMm: finalErr };
  }

  /**
   * Calculates Yoshikawa Manipulability Measure (distance from singularity)
   */
  public computeManipulability(anglesDeg: number[]): number {
    const q2 = (anglesDeg[1] * Math.PI) / 180;
    const q3 = (anglesDeg[2] * Math.PI) / 180;
    // Elbow extension singularity occurs when sin(q3) approaches 0
    const elbowSingularity = Math.abs(Math.sin(q3));
    // Shoulder overhead singularity occurs when arm is vertical
    const shoulderFactor = Math.abs(Math.cos(q2)) * 0.5 + 0.5;
    return Math.max(0.01, Math.min(1.0, elbowSingularity * shoulderFactor));
  }
}

