        const jz = (fkPlus.z - tcpPose.position.z) / delta;

        const dAngle = alpha * (jx * dx + jy * dy + jz * dz);
        angles[j] += dAngle;

        // Clamp to joint limits
        const cfg = DEFAULT_JOINT_CONFIGS[j];
        angles[j] = Math.max(cfg.minDeg, Math.min(cfg.maxDeg, angles[j]));
      }

      // Wrist pitch orient towards target pitch
      angles[3] += (targetPitchDeg - (angles[1] + angles[2] + angles[3])) * 0.1;
      const cfg3 = DEFAULT_JOINT_CONFIGS[3];
      angles[3] = Math.max(cfg3.minDeg, Math.min(cfg3.maxDeg, angles[3]));
    }

    const finalFk = this.forwardKinematics(angles).tcpPose.position;
    const finalErr = Math.sqrt(
      Math.pow(targetPos.x - finalFk.x, 2) +
      Math.pow(targetPos.y - finalFk.y, 2) +
      Math.pow(targetPos.z - finalFk.z, 2)
    );

    return { anglesDeg: angles, converged: finalErr < 5.0, errorMm: finalErr };
  }

  /**
   * Calculates Yoshikawa Manipulability Measure (distance from singularity)
   */
  public computeManipulability(anglesDeg: number[]): number {
    const q2 = (anglesDeg[1] * Math.PI) / 180;
    const q3 = (anglesDeg[2] * Math.PI) / 180;
    // Elbow extension singularity occurs when sin(q3) approaches 0
    const elbowSingularity = Math.abs(Math.sin(q3));
    // Shoulder overhead singularity occurs when arm is vertical
    const shoulderFactor = Math.abs(Math.cos(q2)) * 0.5 + 0.5;
    return Math.max(0.01, Math.min(1.0, elbowSingularity * shoulderFactor));
  }
}

