import { DEFAULT_JOINT_CONFIGS } from '../types/kinematics';
import { ForceTorqueWrench, JointState, Vector3D } from '../types/arm';
import { PowerTelemetry } from '../types/telemetry';

export class DynamicsEngine {
  private motorTemps: number[] = [28, 29, 28, 27, 26, 25];
  private jointVelocities: number[] = [0, 0, 0, 0, 0, 0];
  private actualAngles: number[] = [0, 30, 45, -75, 0, 30]; // Calibrated home pose

  public update(
    dt: number,
    targetAnglesDeg: number[],
    payloadKg: number,
    isEStop: boolean
  ): {
    joints: JointState[];
    power: PowerTelemetry;
    wrench: ForceTorqueWrench;
  } {
    const states: JointState[] = [];
    let totalWatts = 24.5; // Idle base electronics quiescent power

    // Link masses (kg)
    const linkMasses = [4.5, 3.8, 2.6, 1.2, 0.8, 0.5];

    for (let i = 0; i < 6; i++) {
      const cfg = DEFAULT_JOINT_CONFIGS[i];
      let target = targetAnglesDeg[i];

      if (isEStop) {
        target = this.actualAngles[i]; // Freeze commanded target immediately
      }

      // PID position loop response
      const err = target - this.actualAngles[i];
      const maxStep = cfg.maxVelDegPerSec * dt;
      const step = Math.max(-maxStep, Math.min(maxStep, err * 6.0 * dt));

      this.actualAngles[i] += step;
      this.jointVelocities[i] = step / dt;

      // Gravity torque estimation (primarily on J2 and J3)
      let gravityTorque = 0;
      if (i === 1) { // Shoulder
        const rad = (this.actualAngles[1] * Math.PI) / 180;
        gravityTorque = (linkMasses[1] * 0.15 + (linkMasses[2] + payloadKg) * 0.35) * 9.81 * Math.sin(rad);
      } else if (i === 2) { // Elbow
        const rad = ((this.actualAngles[1] + this.actualAngles[2]) * Math.PI) / 180;
        gravityTorque = (linkMasses[2] * 0.13 + payloadKg * 0.28) * 9.81 * Math.sin(rad);
      }

      // Dynamic acceleration torque
      const accelTorque = Math.abs(step / dt) * 0.05;
      const torque = Math.min(cfg.maxTorqueNm, Math.abs(gravityTorque) + accelTorque + 1.2);

      // Motor current (torque constant Kt approx 0.85 Nm/A)
      const current = Number((torque / 0.85 + 0.3).toFixed(2));
      const motorWatts = torque * Math.abs((this.jointVelocities[i] * Math.PI) / 180) + Math.pow(current, 2) * 0.45;
      totalWatts += motorWatts;

      // Thermal model: Joule heating vs ambient dissipation
      const heatGen = (current * current * 0.008) * dt;
      const cooling = (this.motorTemps[i] - 25.0) * 0.012 * dt;
      this.motorTemps[i] = Math.max(25.0, Math.min(85.0, this.motorTemps[i] + heatGen - cooling));

      states.push({
        id: cfg.id,
        name: cfg.name,
        angleDeg: Number(this.actualAngles[i].toFixed(2)),
        targetAngleDeg: Number(target.toFixed(2)),
        velocityDegPerSec: Number(this.jointVelocities[i].toFixed(1)),
        torqueNm: Number(torque.toFixed(2)),
        tempC: Number(this.motorTemps[i].toFixed(1)),
        currentA: current,
        errorDeg: Number(err.toFixed(3)),
      });
    }

    const busVoltage = 48.0 - (totalWatts / 48.0) * 0.08;
    const totalCurrent = Number((totalWatts / busVoltage).toFixed(2));

    // End-effector F/T sensor reading
    const wrench: ForceTorqueWrench = {
      fx: Number((payloadKg * 0.15).toFixed(2)),
      fy: Number((-payloadKg * 9.81 - 1.5).toFixed(2)),
      fz: Number((payloadKg * 0.08).toFixed(2)),
      tx: 0.12,
      ty: 0.05,
      tz: 0.08,
    };

    return {
      joints: states,
      power: {
        busVoltage: Number(busVoltage.toFixed(1)),
        totalCurrent,
        totalWatts: Number(totalWatts.toFixed(1)),
        peakWatts: 340,
      },
      wrench,
    };
  }

  public getActualAngles(): number[] {
    return [...this.actualAngles];
  }

  public setActualAngles(angles: number[]): void {
    this.actualAngles = [...angles];
  }

  public resetToHome(): void {
    this.actualAngles = [0, 30, 45, -75, 0, 30];
    this.jointVelocities = [0, 0, 0, 0, 0, 0];
  }
}

