export class GripperEngine {
  private currentWidthMm = 60.0;
  private targetWidthMm = 60.0;
  private gripForceN = 0.0;
  private workpieces: Workpiece[] = JSON.parse(JSON.stringify(INITIAL_WORKPIECES));
  private grippedObjectId: string | null = null;

  public update(dt: number, commandedWidthMm: number, tcpPos: Vector3D): {
    currentWidthMm: number;
    isGripping: boolean;
    gripForceN: number;
    grippedObjectId: string | null;
    workpieces: Workpiece[];
    totalPayloadKg: number;
  } {
    this.targetWidthMm = Math.max(0, Math.min(60, commandedWidthMm));

    // Move gripper fingers towards commanded width (speed ~120 mm/s)
    const strokeStep = 120 * dt;
    if (this.currentWidthMm < this.targetWidthMm) {
      this.currentWidthMm = Math.min(this.targetWidthMm, this.currentWidthMm + strokeStep);
    } else if (this.currentWidthMm > this.targetWidthMm) {
      this.currentWidthMm = Math.max(this.targetWidthMm, this.currentWidthMm - strokeStep);
    }

    // Check contact and grasp
    if (this.currentWidthMm < 20.0 && !this.grippedObjectId) {
      // Find nearest workpiece within 65mm radius of TCP
      for (const wp of this.workpieces) {
        const dx = wp.position.x - tcpPos.x;
        const dy = wp.position.y - tcpPos.y;
        const dz = wp.position.z - tcpPos.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

        if (dist < 65.0) {
          this.grippedObjectId = wp.id;
          wp.isGripAttached = true;
          this.gripForceN = 35.0; // Clamped nominal grasp force
          break;
        }
      }
    } else if (this.currentWidthMm > 35.0 && this.grippedObjectId) {
      // Release gripped object
      const wp = this.workpieces.find((w) => w.id === this.grippedObjectId);
      if (wp) {
        wp.isGripAttached = false;
        wp.position.y = Math.max(25.0, tcpPos.y - 45.0); // Drop on table
      }
      this.grippedObjectId = null;
      this.gripForceN = 0.0;
    }

    // Update position of attached workpiece with TCP
    let totalPayloadKg = 0.0;
    for (const wp of this.workpieces) {
      if (wp.isGripAttached) {
        wp.position.x = tcpPos.x;
        wp.position.y = Math.max(25.0, tcpPos.y - 35.0);
        wp.position.z = tcpPos.z;
        totalPayloadKg += wp.massKg;
      }
    }

    return {
      currentWidthMm: Number(this.currentWidthMm.toFixed(1)),
      isGripping: this.grippedObjectId !== null,
      gripForceN: Number(this.gripForceN.toFixed(1)),
      grippedObjectId: this.grippedObjectId,
      workpieces: this.workpieces,
      totalPayloadKg: Number(totalPayloadKg.toFixed(2)),
    };
  }

  public reset(): void {
    this.currentWidthMm = 60.0;
    this.targetWidthMm = 60.0;
    this.gripForceN = 0.0;
    this.grippedObjectId = null;
    this.workpieces = JSON.parse(JSON.stringify(INITIAL_WORKPIECES));
  }
}

