import { TrajectoryProgram, Waypoint } from '../types/trajectory';

export class TrajectoryEngine {
  private activeProgram: TrajectoryProgram | null = null;
  private currentWaypointIndex = 0;
  private isRunning = false;
  private dwellTimerSec = 0;
  private onWaypointReached?: (wp: Waypoint) => void;

  public setProgram(program: TrajectoryProgram): void {
    this.activeProgram = program;
    this.currentWaypointIndex = 0;
    this.dwellTimerSec = 0;
    this.isRunning = false;
  }

  public start(): void {
    if (this.activeProgram && this.activeProgram.waypoints.length > 0) {
      this.isRunning = true;
      this.currentWaypointIndex = 0;
      this.dwellTimerSec = 0;
    }
  }

  public pause(): void {
    this.isRunning = false;
  }

  public stop(): void {
    this.isRunning = false;
    this.currentWaypointIndex = 0;
    this.dwellTimerSec = 0;
  }

  public setCallback(cb: (wp: Waypoint) => void): void {
    this.onWaypointReached = cb;
  }

  public update(
    dt: number,
    currentJoints: number[]
  ): {
    commandedJoints: number[];
    commandedGripperWidth: number;
    activeWaypoint: Waypoint | null;
    isExecuting: boolean;
    progressPct: number;
  } {
    if (!this.isRunning || !this.activeProgram) {
      return {
        commandedJoints: [...currentJoints],
        commandedGripperWidth: 60,
        activeWaypoint: null,
        isExecuting: false,
        progressPct: 0,
      };
    }

    const waypoints = this.activeProgram.waypoints;
    const currentWp = waypoints[this.currentWaypointIndex];
    if (!currentWp || !currentWp.jointAnglesDeg) {
      this.isRunning = false;
      return {
        commandedJoints: [...currentJoints],
        commandedGripperWidth: 60,
        activeWaypoint: null,
        isExecuting: false,
        progressPct: 100,
      };
    }

    const targetJoints = currentWp.jointAnglesDeg;
    let maxDist = 0;
    for (let i = 0; i < 6; i++) {
      maxDist = Math.max(maxDist, Math.abs(targetJoints[i] - currentJoints[i]));
    }

    let commandedGripper = 60;
    if (currentWp.gripperAction === 'GRIP') commandedGripper = 10;
    else if (currentWp.gripperAction === 'RELEASE') commandedGripper = 60;

    // Check if reached waypoint within 1.5 degrees
    if (maxDist < 1.5) {
      this.dwellTimerSec += dt;
      if (this.dwellTimerSec >= (currentWp.dwellTimeMs / 1000)) {
        this.dwellTimerSec = 0;
        if (this.onWaypointReached) this.onWaypointReached(currentWp);

        // Advance to next waypoint
        if (this.currentWaypointIndex < waypoints.length - 1) {
          this.currentWaypointIndex++;
        } else if (this.activeProgram.loop) {
          this.currentWaypointIndex = 0;
        } else {
          this.isRunning = false; // Program completed
        }
      }
    }

    const progress = Number(
      (((this.currentWaypointIndex + 1) / waypoints.length) * 100).toFixed(0)
    );

    return {
      commandedJoints: targetJoints,
      commandedGripperWidth: commandedGripper,
      activeWaypoint: currentWp,
      isExecuting: this.isRunning,
      progressPct: progress,
    };
  }

  public getActiveProgram(): TrajectoryProgram | null {
    return this.activeProgram;
  }

  public getStatus(): { isRunning: boolean; index: number } {
    return { isRunning: this.isRunning, index: this.currentWaypointIndex };
  }
}

