class RoboticSoundEngine {
  private ctx: AudioContext | null = null;
  private isMuted = true;
  private servoOsc: OscillatorNode | null = null;
  private servoGain: GainNode | null = null;
  private isInitialized = false;

  private initAudio(): void {
    if (this.isInitialized) return;
    try {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AudioCtx();

      // Servo motor synthesis oscillator
      this.servoOsc = this.ctx.createOscillator();
      this.servoOsc.type = 'sawtooth';
      this.servoOsc.frequency.setValueAtTime(140, this.ctx.currentTime);

      this.servoGain = this.ctx.createGain();
      this.servoGain.gain.setValueAtTime(0.0, this.ctx.currentTime);

      // Lowpass filter to give realistic muffled industrial servo tone
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(1200, this.ctx.currentTime);

      this.servoOsc.connect(filter);
      filter.connect(this.servoGain);
      this.servoGain.connect(this.ctx.destination);
      this.servoOsc.start();

      this.isInitialized = true;
    } catch {
      // AudioContext unavailable or restricted
    }
  }

  public setMute(muted: boolean): void {
    this.isMuted = muted;
    if (!muted && !this.isInitialized) {
      this.initAudio();
    }
    if (this.servoGain && this.ctx) {
      this.servoGain.gain.setValueAtTime(muted ? 0.0 : 0.05, this.ctx.currentTime);
    }
  }

  public updateMotorSound(totalJointVelocity: number): void {
    if (this.isMuted || !this.ctx || !this.servoOsc || !this.servoGain) return;
    const baseFreq = 140;
    const freq = Math.min(800, baseFreq + totalJointVelocity * 2.8);
    this.servoOsc.frequency.setTargetAtTime(freq, this.ctx.currentTime, 0.05);

    const gain = Math.min(0.08, (totalJointVelocity / 300) * 0.08);
    this.servoGain.gain.setTargetAtTime(gain, this.ctx.currentTime, 0.05);
  }

  public playGripperSolenoid(): void {
    if (this.isMuted || !this.ctx) return;
    try {
      // Pneumatic burst noise
      const bufferSize = this.ctx.sampleRate * 0.08;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const output = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        output[i] = Math.random() * 2 - 1;
      }
      const whiteNoise = this.ctx.createBufferSource();
      whiteNoise.buffer = buffer;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'bandpass';
      filter.frequency.setValueAtTime(1800, this.ctx.currentTime);

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0.09, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.08);

      whiteNoise.connect(filter);
      filter.connect(gain);
      gain.connect(this.ctx.destination);
      whiteNoise.start();
    } catch {
      // Ignore audio error
    }
  }

  public playWaypointChime(): void {
    if (this.isMuted || !this.ctx) return;
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1200, this.ctx.currentTime);
      osc.frequency.setValueAtTime(1600, this.ctx.currentTime + 0.04);

      gain.gain.setValueAtTime(0.06, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.15);

      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      osc.stop(this.ctx.currentTime + 0.15);
    } catch {
      // Ignore
    }
  }
}

export const roboticSound = new RoboticSoundEngine();

