import React from 'react';
import {
  AlertOctagon,
  CheckCircle2,
  Cpu,
  Power,
  RotateCcw,
  Volume2,
  VolumeX,
  Zap,
} from 'lucide-react';
import { ControlMode, ServoState, TelemetryFrame } from '../types/telemetry';

interface HeaderProps {
  telemetry: TelemetryFrame;
  servoState: ServoState;
  controlMode: ControlMode;
  isAudioMuted: boolean;
  onToggleServoPower: () => void;
  onToggleEStop: () => void;
  onSelectControlMode: (mode: ControlMode) => void;
  onToggleAudio: () => void;
  onResetToHome: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  telemetry,
  servoState,
  controlMode,
  isAudioMuted,
  onToggleServoPower,
  onToggleEStop,
  onSelectControlMode,
  onToggleAudio,
  onResetToHome,
}) => {
  const isEstop = servoState === 'ESTOP';
  const isEngaged = servoState === 'ENGAGED';

  const modes: { label: string; mode: ControlMode }[] = [
    { label: 'JOINT JOG', mode: 'JOG' },
    { label: 'CARTESIAN IK', mode: 'CARTESIAN' },
    { label: 'TRAJECTORY', mode: 'TRAJECTORY' },
    { label: 'FAT SUITE', mode: 'FAT_CYCLE' },
    { label: 'HOME', mode: 'HOME' },
  ];

  return (
    <header
      className="tactical-panel"
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        height: '62px',
        padding: '0 16px',
        margin: '6px 8px 4px 8px',
        borderLeft: isEstop
          ? '4px solid var(--accent-rose)'
          : isEngaged
          ? '4px solid var(--accent-emerald)'
          : '4px solid var(--accent-amber)',
      }}
    >
      {/* Title & System Status */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        <div
          style={{
            width: '36px',
            height: '36px',
            borderRadius: '6px',
            background: isEstop ? 'rgba(255, 65, 108, 0.2)' : 'rgba(0, 242, 254, 0.15)',
            border: isEstop ? '1px solid var(--accent-rose)' : '1px solid var(--accent-cyan)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <Cpu size={20} color={isEstop ? 'var(--accent-rose)' : 'var(--accent-cyan)'} />
        </div>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span className="tactical-title" style={{ fontSize: '15px', color: '#fff' }}>
              FAUST-KINEMATICS // 6-DOF RIG
            </span>
            <span
              style={{
                fontSize: '10px',
                padding: '2px 6px',
                borderRadius: '4px',
