            {endEffector.gripperWidthMm.toFixed(0)}mm
          </b>
        </span>
        <span>
          PWR: <b style={{ color: '#fff' }}>{power.totalWatts.toFixed(0)}W</b>
        </span>
      </div>
    </div>
  );
};
